\textbf{Claim.}
For
\[
\mathcal W_{\mathrm{ren}}:=\frac{N^\kappa}{2N}
\sum_{\substack{p,q,r\in\Lambda^\ast\\p,q,p+r,q-r\in P_{\mathrm L}}}
\left\langle\varphi_{p+r}\otimes\varphi_{q-r},V_{\mathrm{ren}}\varphi_p\otimes\varphi_q\right\rangle
 a_{p+r}^\ast a_{q-r}^\ast a_pa_q,
\]
one has the operator lower bound
\[
\mathcal W_{\mathrm{ren}}\geq4\pi aN^{1+\kappa}
-CN^\kappa\mathcal N_{>N^\alpha}-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N).
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & P_{\mathrm L}:=\{p\in\Lambda^\ast:|p|\leq N^\alpha\},\quad |P_{\mathrm L}|\leq CN^{3\alpha}.\\[1mm]
(P2) & \mathcal N_{>N^\alpha}:=\sum_{|p|>N^\alpha}a_p^\ast a_p,\quad
       \sum_{q\in P_{\mathrm L}}a_q^\ast a_q=\mathcal N-\mathcal N_{>N^\alpha}.\\[1mm]
(P3) & \mathcal N=N\text{ on the }N\text{-particle sector}.\\[1mm]
(P4) & \text{The paper's estimate of }V_{\mathrm{ren}}\text{ implies the quadratic-form inequality}\\
     & \quad \mathcal W_{\mathrm{ren}}\geq
       \dfrac{4\pi aN^\kappa}{N}
       \sum_{\substack{p,q,r\in\Lambda^\ast\\p,q,p+r,q-r\in P_{\mathrm L}}}
       a_{p+r}^\ast a_{q-r}^\ast a_pa_q
       -CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N).\\[3mm]
(P5) & B_r:=\sum_{\substack{q\in P_{\mathrm L}\\q+r\in P_{\mathrm L}}}a_q^\ast a_{q+r},\quad
       \sum_{\substack{p,q,r\in\Lambda^\ast\\p,q,p+r,q-r\in P_{\mathrm L}}}
       a_{p+r}^\ast a_{q-r}^\ast a_pa_q
       =\sum_{r\in\Lambda^\ast}B_r^\ast B_r-
       \sum_{\substack{p,r\in\Lambda^\ast\\p,p+r\in P_{\mathrm L}}}a_{p+r}^\ast a_{p+r}.\\[3mm]
(P6) & \sum_{r\in\Lambda^\ast}B_r^\ast B_r\geq B_0^\ast B_0,
       \quad B_0=\sum_{q\in P_{\mathrm L}}a_q^\ast a_q.\\[1mm]
(P7) & \sum_{\substack{p,r\in\Lambda^\ast\\p,p+r\in P_{\mathrm L}}}a_{p+r}^\ast a_{p+r}
       \leq |P_{\mathrm L}|\mathcal N\leq CN^{1+3\alpha}.\\[1mm]
(P8) & (N-X)^2\geq N^2-2NX\text{ for every self-adjoint }X\geq0.
\end{array}
\]

\textbf{Derivation.}
Use the replacement of \(V_{\mathrm{ren}}\) by \(8\pi a\):
\begin{align}
\mathcal W_{\mathrm{ren}}
&\geq
\frac{4\pi aN^\kappa}{N}
\sum_{\substack{p,q,r\in\Lambda^\ast\\p,q,p+r,q-r\in P_{\mathrm L}}}
 a_{p+r}^\ast a_{q-r}^\ast a_pa_q
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N)
\qquad \text{by }(P4)\\
&=\frac{4\pi aN^\kappa}{N}
\left(\sum_{r\in\Lambda^\ast}B_r^\ast B_r-
\sum_{\substack{p,r\in\Lambda^\ast\\p,p+r\in P_{\mathrm L}}}a_{p+r}^\ast a_{p+r}\right)
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N)
\qquad \text{by }(P5)\\
&\geq\frac{4\pi aN^\kappa}{N}B_0^\ast B_0
-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N)
\qquad \text{by }(P6),(P7).
\end{align}
Now identify \(B_0\) and expand the square:
\begin{align}
B_0^\ast B_0
&=\left(\sum_{q\in P_{\mathrm L}}a_q^\ast a_q\right)^2
       \qquad \text{by }(P6)\\
&=(\mathcal N-\mathcal N_{>N^\alpha})^2
       \qquad \text{by }(P2)\\
&\geq N^2-2N\mathcal N_{>N^\alpha}
       \qquad \text{by }(P3),(P8).
\end{align}
Substitution gives
\begin{align}
\mathcal W_{\mathrm{ren}}
&\geq\frac{4\pi aN^\kappa}{N}
\left(N^2-2N\mathcal N_{>N^\alpha}\right)
-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N)\\
&=4\pi aN^{1+\kappa}-8\pi aN^\kappa\mathcal N_{>N^\alpha}
-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N)\\
&\geq4\pi aN^{1+\kappa}-CN^\kappa\mathcal N_{>N^\alpha}
-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N),
\end{align}
where the last line absorbs \(8\pi a\) into the constant \(C\).

\textbf{Final Result.}
\[
\boxed{\mathcal W_{\mathrm{ren}}\geq4\pi aN^{1+\kappa}
-CN^\kappa\mathcal N_{>N^\alpha}-CN^{\kappa+3\alpha}
-CN^{2\kappa+2\alpha-1}(\mathcal K+\mathcal N).}
\]
\hfill$\blacksquare$
